import { useEffect, type RefObject } from 'react';
import { useBuilderStore } from '../store';
import { getNodeMoveCapabilities } from '../utils/nodeMoveActions';

function isEditingControlEvent(event: KeyboardEvent): boolean {
  // The document's active element is the shadow host, not the input or
  // overlay receiving the shortcut. The composed path includes both.
  return event.composedPath().some((target) => target instanceof Element && (
    target.matches('input, textarea, select, dialog, [role="textbox"], [role="combobox"], [role="listbox"], [role="menu"], [role="dialog"]')
    || (target instanceof HTMLElement && target.isContentEditable)
  ));
}

function getSelectedMoveNodeId(
  selectedNodeIds: number[],
  lastSelectedNodeId: number | null,
): number | null {
  if (selectedNodeIds.length === 0) {
    return null;
  }

  if (lastSelectedNodeId !== null && selectedNodeIds.includes(lastSelectedNodeId)) {
    return lastSelectedNodeId;
  }

  return selectedNodeIds[selectedNodeIds.length - 1] ?? null;
}

/** Alt/Option + arrow keys reorder the highlighted row when nothing else is focused. */
export function useNodeTreeKeyboardShortcuts(
  enabled: boolean,
  treeContainerRef: RefObject<HTMLDivElement | null>,
): void {
  const moveNodeUp = useBuilderStore((s) => s.moveNodeUp);
  const moveNodeDown = useBuilderStore((s) => s.moveNodeDown);
  const indent = useBuilderStore((s) => s.indent);
  const outdent = useBuilderStore((s) => s.outdent);

  useEffect(() => {
    if (!enabled) {
      return;
    }

    let scrollFrame: number | null = null;

    const handleKeyDown = (event: KeyboardEvent) => {
      if (!event.altKey || event.metaKey || event.ctrlKey || event.shiftKey) {
        return;
      }

      if (event.defaultPrevented || isEditingControlEvent(event)) {
        return;
      }

      const { selectedNodeIds, lastSelectedNodeId, nodes, state } = useBuilderStore.getState();
      const nodeId = getSelectedMoveNodeId(selectedNodeIds, lastSelectedNodeId);

      if (nodeId === null) {
        return;
      }

      const node = nodes.find((candidate) => candidate.id === nodeId);

      if (!node || node.pendingDelete) {
        return;
      }

      const maxLevels = state?.menu.maxLevels ?? null;
      const capabilities = getNodeMoveCapabilities(nodes, nodeId, maxLevels);

      let handled = false;

      switch (event.key) {
        case 'ArrowUp':
          if (capabilities.canMoveUp) {
            moveNodeUp(nodeId);
            handled = true;
          }
          break;
        case 'ArrowDown':
          if (capabilities.canMoveDown) {
            moveNodeDown(nodeId);
            handled = true;
          }
          break;
        case 'ArrowLeft':
          if (capabilities.canMoveLeft) {
            outdent(nodeId);
            handled = true;
          }
          break;
        case 'ArrowRight':
          if (capabilities.canMoveRight) {
            indent(nodeId);
            handled = true;
          }
          break;
      }

      if (handled) {
        event.preventDefault();
        if (scrollFrame !== null) {
          cancelAnimationFrame(scrollFrame);
        }

        // Rows live inside the builder's shadow root. Wait for the reordered
        // tree to render before scrolling to the row's new position.
        scrollFrame = requestAnimationFrame(() => {
          scrollFrame = null;
          const row = treeContainerRef.current?.querySelector<HTMLElement>(`[data-node-id="${nodeId}"]`);
          if (!row) {
            return;
          }

          // Craft fixes the page header while scrolling. Reserve its height
          // so upward moves do not hide the selected row underneath it.
          const headerHeight = row.ownerDocument.getElementById('header')?.getBoundingClientRect().height ?? 0;
          const scrollMarginTop = row.style.scrollMarginTop;
          // Round outwards for browsers that align scroll offsets to whole pixels.
          row.style.scrollMarginTop = `${Math.ceil(headerHeight) + 1}px`;
          row.scrollIntoView({ block: 'nearest', inline: 'nearest' });
          row.style.scrollMarginTop = scrollMarginTop;
        });
      }
    };

    window.addEventListener('keydown', handleKeyDown);

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      if (scrollFrame !== null) {
        cancelAnimationFrame(scrollFrame);
      }
    };
  }, [enabled, indent, moveNodeDown, moveNodeUp, outdent, treeContainerRef]);
}
